"use client";

import { NoteRoot } from "./note-root";
import { NoteTrigger } from "./note-trigger";
import { NotePanel } from "./note-panel";

export { LineGutter } from "./line-gutter";
export { NoteRoot, NoteTrigger, NotePanel };
export type {
  NoteContextValue,
  NotePlacement,
  NoteRootProps,
} from "./note-root";
export type { NoteTriggerProps } from "./note-trigger";

export const Note = {
  Root: NoteRoot,
  Trigger: NoteTrigger,
  Panel: NotePanel,
};

"use client";

import * as React from "react";

export type NotePlacement =
  | "auto"
  | "top-left"
  | "top-right"
  | "bottom-left"
  | "bottom-right";

export interface NoteRootProps {
  children: React.ReactNode;
  storageKey?: string;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  defaultOpen?: boolean;
  value?: string;
  onValueChange?: (value: string) => void;
  placement?: NotePlacement;
  width?: number;
  height?: number;
  breakpoint?: number;
  showLineNumbers?: boolean;
}

export interface NoteContextValue {
  open: boolean;
  requestClose: () => void;
  setOpen: (open: boolean) => void;
  value: string;
  setValue: (value: string) => void;
  storageKey: string;
  placement: NotePlacement;
  width: number;
  height: number;
  breakpoint: number;
  showLineNumbers: boolean;
  panelId: string;
  triggerRef: React.MutableRefObject<HTMLButtonElement | null>;
  registerTrigger: (element: HTMLButtonElement | null) => void;
}

const NoteContext = React.createContext<NoteContextValue | null>(null);

export function useNoteContext() {
  const context = React.useContext(NoteContext);
  if (!context) {
    throw new Error("Note components must be rendered inside Note.Root.");
  }
  return context;
}

export function NoteRoot({
  children,
  storageKey = "peel-note:v1",
  open: controlledOpen,
  onOpenChange,
  defaultOpen = false,
  value: controlledValue,
  onValueChange,
  placement = "auto",
  width = 380,
  height = 340,
  breakpoint = 640,
  showLineNumbers = true,
}: NoteRootProps) {
  const [internalOpen, setInternalOpen] = React.useState(defaultOpen);
  const [internalValue, setInternalValue] = React.useState("");
  const [loadedStorageKey, setLoadedStorageKey] = React.useState<string | null>(
    null
  );
  const isOpenControlled = controlledOpen !== undefined;
  const isValueControlled = controlledValue !== undefined;
  const open = isOpenControlled ? controlledOpen : internalOpen;
  const value = isValueControlled ? controlledValue : internalValue;
  const triggerRef = React.useRef<HTMLButtonElement | null>(null);
  const valueRef = React.useRef(value);
  const writeTimerRef = React.useRef<number | null>(null);
  const panelId = React.useId();

  React.useEffect(() => {
    valueRef.current = value;
  }, [value]);

  React.useEffect(() => {
    let storedValue: string | null = null;
    try {
      storedValue = window.localStorage.getItem(storageKey);
    } catch (error) {
      console.error("Unable to read the saved note from local storage.", error);
    }

    if (!isValueControlled && storedValue !== null) {
      // Restoring client-only storage is the reason this effect updates state.
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setInternalValue(storedValue);
    }
    setLoadedStorageKey(storageKey);
  }, [isValueControlled, storageKey]);

  const writeValue = React.useCallback(
    (nextValue: string) => {
      try {
        window.localStorage.setItem(storageKey, nextValue);
      } catch (error) {
        console.error("Unable to save the note to local storage.", error);
      }
    },
    [storageKey]
  );

  React.useEffect(() => {
    if (loadedStorageKey !== storageKey) return;

    if (writeTimerRef.current !== null) {
      window.clearTimeout(writeTimerRef.current);
    }
    writeTimerRef.current = window.setTimeout(() => {
      writeValue(value);
      writeTimerRef.current = null;
    }, 250);

    return () => {
      if (writeTimerRef.current !== null) {
        window.clearTimeout(writeTimerRef.current);
        writeTimerRef.current = null;
      }
    };
  }, [loadedStorageKey, storageKey, value, writeValue]);

  React.useEffect(() => {
    const saveImmediately = () => {
      if (writeTimerRef.current !== null) {
        window.clearTimeout(writeTimerRef.current);
        writeTimerRef.current = null;
      }
      writeValue(valueRef.current);
    };
    window.addEventListener("pagehide", saveImmediately);
    return () => window.removeEventListener("pagehide", saveImmediately);
  }, [writeValue]);

  React.useEffect(
    () => () => {
      if (writeTimerRef.current !== null) {
        window.clearTimeout(writeTimerRef.current);
        writeValue(valueRef.current);
        writeTimerRef.current = null;
      }
    },
    [writeValue]
  );

  const setOpen = React.useCallback(
    (nextOpen: boolean) => {
      if (nextOpen === open) return;
      if (!isOpenControlled) setInternalOpen(nextOpen);
      onOpenChange?.(nextOpen);
    },
    [isOpenControlled, onOpenChange, open]
  );

  const requestClose = React.useCallback(() => {
    setOpen(false);
  }, [setOpen]);

  const setValue = React.useCallback(
    (nextValue: string) => {
      if (!isValueControlled) setInternalValue(nextValue);
      onValueChange?.(nextValue);
    },
    [isValueControlled, onValueChange]
  );

  const registerTrigger = React.useCallback(
    (element: HTMLButtonElement | null) => {
      triggerRef.current = element;
    },
    []
  );

  const contextValue = React.useMemo<NoteContextValue>(
    () => ({
      open,
      requestClose,
      setOpen,
      value,
      setValue,
      storageKey,
      placement,
      width,
      height,
      breakpoint,
      showLineNumbers,
      panelId,
      triggerRef,
      registerTrigger,
    }),
    [
      open,
      requestClose,
      setOpen,
      value,
      setValue,
      storageKey,
      placement,
      width,
      height,
      breakpoint,
      showLineNumbers,
      panelId,
      registerTrigger,
    ]
  );

  return (
    <NoteContext.Provider value={contextValue}>
      {children}
    </NoteContext.Provider>
  );
}

"use client";

import * as React from "react";
import { NotebookPen } from "lucide-react";
import { useNoteContext } from "./note-root";

export interface NoteTriggerProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onClick"> {
  onClick?: React.MouseEventHandler<HTMLButtonElement>;
}

export const NoteTrigger = React.forwardRef<
  HTMLButtonElement,
  NoteTriggerProps
>(function NoteTrigger(
  {
    children,
    className,
    disabled,
    onClick,
    type = "button",
    ...buttonProps
  },
  forwardedRef
) {
  const { open, setOpen, panelId, registerTrigger } = useNoteContext();

  const setRefs = React.useCallback(
    (element: HTMLButtonElement | null) => {
      registerTrigger(element);
      if (typeof forwardedRef === "function") forwardedRef(element);
      else if (forwardedRef) forwardedRef.current = element;
    },
    [forwardedRef, registerTrigger]
  );

  return (
    <button
      {...buttonProps}
      ref={setRefs}
      type={type}
      disabled={disabled}
      aria-label={buttonProps["aria-label"] ?? "Notes"}
      aria-expanded={open}
      aria-controls={panelId}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented && !disabled) setOpen(!open);
      }}
      className={[
        "inline-flex size-11 items-center justify-center rounded-full border border-white/[0.12] bg-[#1f1f21] text-[#c4c4cc] shadow-[0_2px_8px_rgba(0,0,0,0.35)] transition-colors hover:bg-[#2a2a2d] hover:text-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#84ff00] focus-visible:ring-offset-2 focus-visible:ring-offset-black disabled:cursor-not-allowed disabled:opacity-50",
        className,
      ]
        .filter(Boolean)
        .join(" ")}
    >
      {children ?? <NotebookPen aria-hidden="true" className="size-4" />}
    </button>
  );
});

NoteTrigger.displayName = "NoteTrigger";

"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import { Maximize2, Minimize2, X } from "lucide-react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { LineGutter } from "./line-gutter";
import { useNoteContext } from "./note-root";

gsap.registerPlugin(useGSAP);

const subscribeToNothing = () => () => {};
const getClientMountedSnapshot = () => true;
const getServerMountedSnapshot = () => false;

function getFourCornerRadius(trigger: HTMLElement) {
  const rectangle = trigger.getBoundingClientRect();
  const computedRadius = window.getComputedStyle(trigger).borderRadius;
  const values = computedRadius.split("/")[0].trim().split(/\s+/);
  const fourValues =
    values.length === 1
      ? [values[0], values[0], values[0], values[0]]
      : values.length === 2
        ? [values[0], values[1], values[0], values[1]]
        : values.length === 3
          ? [values[0], values[1], values[2], values[1]]
          : values.slice(0, 4);

  return fourValues
    .map((value) => {
      const amount = Number.parseFloat(value);
      const pixels = value.endsWith("%")
        ? (Math.min(rectangle.width, rectangle.height) * amount) / 100
        : amount;
      return `${Math.min(Math.max(0, pixels), Math.min(rectangle.width, rectangle.height) / 2)}px`;
    })
    .join(" ");
}

function getTargetBounds(
  trigger: HTMLElement,
  width: number,
  height: number,
  placement: ReturnType<typeof useNoteContext>["placement"]
) {
  const triggerRect = trigger.getBoundingClientRect();
  const viewportWidth = window.innerWidth;
  const viewportHeight = window.innerHeight;
  const targetWidth = Math.max(1, Math.min(width, viewportWidth - 48));
  const targetHeight = Math.max(1, Math.min(height, viewportHeight - 72));
  const autoRight =
    triggerRect.left + triggerRect.width / 2 >= viewportWidth / 2;
  const autoBottom =
    triggerRect.top + triggerRect.height / 2 >= viewportHeight / 2;
  const right = placement === "auto" ? autoRight : placement.endsWith("right");
  const bottom =
    placement === "auto" ? autoBottom : placement.startsWith("bottom");
  const targetLeft = right
    ? triggerRect.right - targetWidth
    : triggerRect.left;
  const targetTop = bottom
    ? triggerRect.bottom - targetHeight
    : triggerRect.top;

  return {
    left: Math.max(16, Math.min(targetLeft, viewportWidth - targetWidth - 16)),
    top: Math.max(16, Math.min(targetTop, viewportHeight - targetHeight - 16)),
    width: targetWidth,
    height: targetHeight,
    borderRadius: "22px 22px 22px 22px",
  };
}

export function NotePanel() {
  const {
    open,
    requestClose,
    value,
    setValue,
    width,
    height,
    breakpoint,
    placement,
    showLineNumbers,
    panelId,
    triggerRef,
  } = useNoteContext();
  const panelRef = React.useRef<HTMLDivElement>(null);
  const contentRef = React.useRef<HTMLDivElement>(null);
  const textareaRef = React.useRef<HTMLTextAreaElement>(null);
  const scrimRef = React.useRef<HTMLDivElement>(null);
  const timelineRef = React.useRef<gsap.core.Timeline | null>(null);
  const fullscreenRef = React.useRef(false);
  const hasOpenedRef = React.useRef(false);
  const fullscreenHandlerRef = React.useRef<() => void>(() => {});
  const removeViewportListenersRef = React.useRef<(() => void) | null>(null);
  const mounted = React.useSyncExternalStore(
    subscribeToNothing,
    getClientMountedSnapshot,
    getServerMountedSnapshot
  );
  const [isMobile, setIsMobile] = React.useState(
    () => typeof window !== "undefined" && window.innerWidth < breakpoint
  );
  const [isFullscreen, setIsFullscreen] = React.useState(false);

  React.useEffect(() => {
    const updateViewportMode = () => {
      setIsMobile(window.innerWidth < breakpoint);
    };
    window.addEventListener("resize", updateViewportMode);
    return () => window.removeEventListener("resize", updateViewportMode);
  }, [breakpoint]);

  useGSAP(
    (_, contextSafe) => {
      if (!mounted) return;
      const makeContextSafe =
        contextSafe ?? ((callback: () => void) => callback);

      const panel = panelRef.current;
      const trigger = triggerRef.current;
      if (!panel || !trigger) return;

      timelineRef.current?.kill();
      removeViewportListenersRef.current?.();
      removeViewportListenersRef.current = null;

      const safeToggleFullscreen = makeContextSafe(() => {
        if (!open) return;
        timelineRef.current?.kill();
        const nextFullscreen = !fullscreenRef.current;
        fullscreenRef.current = nextFullscreen;
        setIsFullscreen(nextFullscreen);

        if (isMobile) {
          const viewportHeight =
            window.visualViewport?.height ?? window.innerHeight;
          gsap.to(panel, {
            height: nextFullscreen
              ? "calc(100dvh - max(12px, env(safe-area-inset-top, 0px) + 8px))"
              : "60dvh",
            maxHeight: `${Math.max(160, viewportHeight - 16)}px`,
            bottom: 0,
            borderRadius: nextFullscreen
              ? "22px 22px 0px 0px"
              : "26px 26px 0px 0px",
            duration: 0.65,
            ease: "expo.inOut",
            overwrite: "auto",
          });
          return;
        }

        const target = nextFullscreen
          ? {
              left: 16,
              top: 16,
              width: window.innerWidth - 32,
              height: window.innerHeight - 32,
              borderRadius: "22px 22px 22px 22px",
            }
          : getTargetBounds(trigger, width, height, placement);

        gsap.to(panel, {
          ...target,
          duration: 0.65,
          ease: "expo.inOut",
          overwrite: "auto",
        });
      });
      fullscreenHandlerRef.current = safeToggleFullscreen;

      const safeViewportUpdate = makeContextSafe(() => {
        if (!open || !isMobile) return;
        const viewport = window.visualViewport;
        const keyboardHeight = viewport
          ? Math.max(
              0,
              window.innerHeight - viewport.height - viewport.offsetTop
            )
          : 0;
        const availableHeight = viewport
          ? Math.max(160, viewport.height - 16)
          : Math.max(160, window.innerHeight - 16);

        gsap.to(panel, {
          bottom: keyboardHeight,
          maxHeight: `${availableHeight}px`,
          duration: 0.25,
          ease: "power2.out",
          overwrite: "auto",
        });
      });
      if (open) {
        const wasVisible = panel.style.visibility === "visible";
        const timeline = gsap.timeline();
        timelineRef.current = timeline;
        panel.style.visibility = "visible";
        panel.style.pointerEvents = "auto";

        if (isMobile) {
          gsap.set(panel, {
            position: "fixed",
            top: "auto",
            left: 0,
            right: 0,
            bottom: 0,
            width: "100%",
            height: fullscreenRef.current
              ? "calc(100dvh - max(12px, env(safe-area-inset-top, 0px) + 8px))"
              : "60dvh",
            maxHeight: "calc(100dvh - 16px)",
            borderRadius: fullscreenRef.current
              ? "22px 22px 0px 0px"
              : "26px 26px 0px 0px",
            ...(wasVisible ? {} : { yPercent: 100 }),
          });
          gsap.set(scrimRef.current, { autoAlpha: wasVisible ? 1 : 0 });
          if (!wasVisible) {
            timeline.to(scrimRef.current, {
              autoAlpha: 1,
              duration: 0.4,
              ease: "power2.out",
            });
          }
          timeline.to(
            panel,
            { yPercent: 0, duration: 0.65, ease: "expo.out" },
            0
          );
          if (contentRef.current) {
            timeline.to(
              contentRef.current,
              { opacity: 1, y: 0, duration: 0.35, ease: "power2.out" },
              wasVisible ? 0 : 0.22
            );
          }
        } else {
          const triggerRect = trigger.getBoundingClientRect();
          if (!wasVisible) {
            gsap.set(panel, {
              position: "fixed",
              left: triggerRect.left,
              top: triggerRect.top,
              width: triggerRect.width,
              height: triggerRect.height,
              borderRadius: getFourCornerRadius(trigger),
              yPercent: 0,
            });
            gsap.set(trigger, {
              opacity: 1,
              scale: 1,
              transformOrigin: "center",
            });
            if (contentRef.current) {
              gsap.set(contentRef.current, { opacity: 0, y: 10 });
            }
            timeline.to(
              trigger,
              {
                opacity: 0,
                scale: 0.7,
                duration: 0.2,
                ease: "power2.in",
              },
              0
            );
          } else {
            gsap.set(trigger, { opacity: 0, scale: 0.7 });
            const currentRect = panel.getBoundingClientRect();
            gsap.set(panel, {
              left: currentRect.left,
              top: currentRect.top,
              width: currentRect.width,
              height: currentRect.height,
              yPercent: 0,
            });
          }

          const target = fullscreenRef.current
            ? {
                left: 16,
                top: 16,
                width: window.innerWidth - 32,
                height: window.innerHeight - 32,
                borderRadius: "22px 22px 22px 22px",
              }
            : getTargetBounds(trigger, width, height, placement);

          timeline.to(
            panel,
            {
              ...target,
              duration: 0.75,
              ease: "expo.inOut",
              overwrite: "auto",
            },
            0
          );
          if (contentRef.current) {
            timeline.to(
              contentRef.current,
              { opacity: 1, y: 0, duration: 0.4, ease: "power2.out" },
              wasVisible ? 0 : 0.34
            );
          }
        }

        timeline.eventCallback("onComplete", () => {
          if (open) textareaRef.current?.focus({ preventScroll: true });
        });
        hasOpenedRef.current = true;
      } else if (hasOpenedRef.current) {
        const timeline = gsap.timeline({
          onComplete: () => {
            panel.style.visibility = "hidden";
            panel.style.pointerEvents = "none";
            fullscreenRef.current = false;
            setIsFullscreen(false);
            trigger.focus({ preventScroll: true });
          },
        });
        timelineRef.current = timeline;

        if (isMobile) {
          if (contentRef.current) {
            timeline.to(
              contentRef.current,
              { opacity: 0, y: 6, duration: 0.18, ease: "power2.in" },
              0
            );
          }
          timeline.to(
            panel,
            { yPercent: 100, duration: 0.65, ease: "expo.in" },
            0.06
          );
          timeline.to(
            scrimRef.current,
            { autoAlpha: 0, duration: 0.4, ease: "power2.in" },
            0
          );
        } else {
          gsap.set(trigger, { scale: 1, transformOrigin: "center" });
          const triggerRect = trigger.getBoundingClientRect();
          const triggerRadius = getFourCornerRadius(trigger);
          if (contentRef.current) {
            timeline.to(
              contentRef.current,
              { opacity: 0, y: 6, duration: 0.18, ease: "power2.in" },
              0
            );
          }
          timeline.to(
            panel,
            {
              left: triggerRect.left,
              top: triggerRect.top,
              width: triggerRect.width,
              height: triggerRect.height,
              borderRadius: triggerRadius,
              duration: 0.65,
              ease: "expo.inOut",
              overwrite: "auto",
            },
            0.06
          );
          timeline.fromTo(
            trigger,
            { opacity: 0, scale: 0.7, transformOrigin: "center" },
            {
              opacity: 1,
              scale: 1,
              duration: 0.4,
              ease: "back.out(2)",
            },
            0.5
          );
        }
      }

      const viewport = window.visualViewport;
      if (open && isMobile && viewport) {
        viewport.addEventListener("resize", safeViewportUpdate);
        viewport.addEventListener("scroll", safeViewportUpdate);
        removeViewportListenersRef.current = () => {
          viewport.removeEventListener("resize", safeViewportUpdate);
          viewport.removeEventListener("scroll", safeViewportUpdate);
        };
        safeViewportUpdate();
      }

      return undefined;
    },
    {
      scope: panelRef,
      dependencies: [mounted, open, isMobile, width, height, placement],
    }
  );

  React.useEffect(
    () => () => {
      timelineRef.current?.kill();
      removeViewportListenersRef.current?.();
    },
    []
  );

  const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "Escape") {
      event.preventDefault();
      requestClose();
      return;
    }
    if (event.key !== "Tab" || !panelRef.current) return;

    const focusable = panelRef.current.querySelectorAll<HTMLElement>(
      'button:not([disabled]), textarea:not([disabled]), [href], input:not([disabled]), [tabindex]:not([tabindex="-1"])'
    );
    if (focusable.length === 0) return;

    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    if (event.shiftKey && document.activeElement === first) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault();
      first.focus();
    }
  };

  if (!mounted) return null;

  return createPortal(
    <>
      <div
        ref={scrimRef}
        aria-hidden="true"
        onClick={requestClose}
        className="fixed inset-0 z-[9998] bg-black/[0.28]"
        style={{
          opacity: 0,
          visibility: "hidden",
          pointerEvents: open && isMobile ? "auto" : "none",
          backdropFilter: "blur(10px)",
          WebkitBackdropFilter: "blur(10px)",
        }}
      />
      <div
        ref={panelRef}
        id={panelId}
        role="dialog"
        aria-label="Notes"
        aria-modal={open || undefined}
        aria-hidden={!open}
        onKeyDown={handleKeyDown}
        className="fixed z-[9999] box-border flex min-h-0 flex-col overflow-hidden border-[3px] border-black bg-[#1f1f21] text-[#e8e8ea] shadow-[0_0_0_1px_rgba(255,255,255,0.14),0_22px_50px_-14px_rgba(0,0,0,0.5)]"
        style={{
          left: 0,
          top: 0,
          width: 0,
          height: 0,
          borderRadius: "22px 22px 22px 22px",
          visibility: "hidden",
          pointerEvents: "none",
          boxSizing: "border-box",
          opacity: 1,
        }}
      >
        <div
          ref={contentRef}
          className="flex min-h-0 flex-1 flex-col"
          style={{ opacity: 0, transform: "translateY(10px)" }}
        >
          <div className="relative flex min-h-0 flex-1 overflow-hidden">
            <LineGutter
              textareaRef={textareaRef}
              value={value}
              showLineNumbers={showLineNumbers}
            />
            <textarea
              ref={textareaRef}
              value={value}
              onChange={(event) => setValue(event.currentTarget.value)}
              aria-label="Note text"
              placeholder="Write a note..."
              spellCheck
              className="note-button-editor relative z-0 min-h-0 min-w-0 flex-1 resize-none overflow-y-auto bg-transparent px-3 py-3 font-mono text-[13px] leading-[22px] text-[#e8e8ea] caret-[#84ff00] outline-none placeholder:text-zinc-600 selection:bg-[#84ff00]/30 selection:text-white"
              style={{
                scrollbarWidth: "none",
                overflowWrap: "anywhere",
                whiteSpace: "pre-wrap",
                wordBreak: "normal",
                tabSize: 2,
              }}
            />
            <style>{`
              .note-button-editor::-webkit-scrollbar { display: none; }
            `}</style>
          </div>
        </div>

        <div className="absolute right-0 top-0 flex h-11 items-center gap-1 rounded-bl-xl bg-black pl-2 pr-1">
          <button
            type="button"
            aria-label={isFullscreen ? "Exit fullscreen" : "Enter fullscreen"}
            aria-pressed={isFullscreen}
            onClick={() => fullscreenHandlerRef.current()}
            className="inline-flex size-10 items-center justify-center rounded-lg text-[#c4c4cc] transition-colors hover:bg-white/[0.12] hover:text-white focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-[#84ff00] sm:size-[30px]"
          >
            {isFullscreen ? (
              <Minimize2 aria-hidden="true" className="size-3.5" />
            ) : (
              <Maximize2 aria-hidden="true" className="size-3.5" />
            )}
          </button>
          <button
            type="button"
            aria-label="Close notes"
            onClick={requestClose}
            className="inline-flex size-10 items-center justify-center rounded-lg text-[#c4c4cc] transition-colors hover:bg-white/[0.12] hover:text-white focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-[#84ff00] sm:size-[30px]"
          >
            <X aria-hidden="true" className="size-4" />
          </button>
        </div>
      </div>
    </>,
    document.body
  );
}

"use client";

import * as React from "react";

interface LineGutterProps {
  textareaRef: React.RefObject<HTMLTextAreaElement | null>;
  value: string;
  showLineNumbers: boolean;
}

interface MirrorMetrics {
  width: number;
  fontFamily: string;
  fontSize: string;
  fontWeight: string;
  fontStyle: string;
  lineHeight: string;
  letterSpacing: string;
  paddingTop: string;
  paddingRight: string;
  paddingBottom: string;
  paddingLeft: string;
  boxSizing: string;
  tabSize: string;
}

const defaultLineHeight = 22;

export function LineGutter({
  textareaRef,
  value,
  showLineNumbers,
}: LineGutterProps) {
  const lines = value.split("\n");
  const mirrorRef = React.useRef<HTMLDivElement>(null);
  const mirrorLineRefs = React.useRef<Array<HTMLDivElement | null>>([]);
  const [metrics, setMetrics] = React.useState<MirrorMetrics | null>(null);
  const [lineHeights, setLineHeights] = React.useState<number[]>(
    () => lines.map(() => defaultLineHeight)
  );
  const [scrollTop, setScrollTop] = React.useState(0);

  React.useLayoutEffect(() => {
    const textarea = textareaRef.current;
    if (!textarea || !mirrorRef.current) return;

    let frame = 0;
    const measure = () => {
      const computed = window.getComputedStyle(textarea);
      setMetrics({
        width: textarea.clientWidth,
        fontFamily: computed.fontFamily,
        fontSize: computed.fontSize,
        fontWeight: computed.fontWeight,
        fontStyle: computed.fontStyle,
        lineHeight: computed.lineHeight,
        letterSpacing: computed.letterSpacing,
        paddingTop: computed.paddingTop,
        paddingRight: computed.paddingRight,
        paddingBottom: computed.paddingBottom,
        paddingLeft: computed.paddingLeft,
        boxSizing: computed.boxSizing,
        tabSize: computed.tabSize,
      });

      window.cancelAnimationFrame(frame);
      frame = window.requestAnimationFrame(() => {
        const nextHeights = mirrorLineRefs.current.map(
          (line) => line?.offsetHeight ?? defaultLineHeight
        );
        setLineHeights((previous) =>
          previous.length === nextHeights.length &&
          previous.every((height, index) => height === nextHeights[index])
            ? previous
            : nextHeights
        );
      });
    };

    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(textarea);
    return () => {
      observer.disconnect();
      window.cancelAnimationFrame(frame);
    };
  }, [textareaRef, value]);

  React.useEffect(() => {
    const textarea = textareaRef.current;
    if (!textarea) return;

    const syncScroll = () => setScrollTop(textarea.scrollTop);
    textarea.addEventListener("scroll", syncScroll, { passive: false });
    syncScroll();
    return () => textarea.removeEventListener("scroll", syncScroll);
  }, [textareaRef]);

  return (
    <>
      {showLineNumbers && (
        <div
          aria-hidden="true"
          className="relative z-10 w-11 shrink-0 overflow-hidden border-r border-white/[0.06] bg-[#1b1b1d] pt-3"
        >
          <div
            className="will-change-transform"
            style={{ transform: `translateY(-${scrollTop}px)` }}
          >
            {lines.map((_, index) => (
              <div
                key={index}
                className="pr-2 text-right font-mono text-xs leading-[22px] tabular-nums text-[#6b6b74]"
                style={{
                  height: `${lineHeights[index] ?? defaultLineHeight}px`,
                }}
              >
                {index + 1}
              </div>
            ))}
          </div>
        </div>
      )}

      <div
        aria-hidden="true"
        className="pointer-events-none absolute left-0 top-0 h-0 overflow-hidden"
        style={{ visibility: "hidden" }}
      >
        <div
          ref={mirrorRef}
          className="whitespace-pre-wrap"
          style={{
            width: metrics ? `${metrics.width}px` : 0,
            fontFamily: metrics?.fontFamily ?? "Geist Mono, ui-monospace, monospace",
            fontSize: metrics?.fontSize ?? "13px",
            fontWeight: metrics?.fontWeight ?? "400",
            fontStyle: metrics?.fontStyle ?? "normal",
            lineHeight: metrics?.lineHeight ?? `${defaultLineHeight}px`,
            letterSpacing: metrics?.letterSpacing ?? "normal",
            paddingTop: metrics?.paddingTop ?? "12px",
            paddingRight: metrics?.paddingRight ?? "12px",
            paddingBottom: metrics?.paddingBottom ?? "12px",
            paddingLeft: metrics?.paddingLeft ?? "12px",
            boxSizing:
              metrics?.boxSizing === "content-box" ? "content-box" : "border-box",
            tabSize: metrics?.tabSize ?? 2,
            overflowWrap: "anywhere",
            wordBreak: "normal",
          }}
        >
          {lines.map((line, index) => (
            <div
              key={index}
              ref={(element) => {
                mirrorLineRefs.current[index] = element;
              }}
              className="whitespace-pre-wrap"
              style={{
                minHeight: metrics?.lineHeight ?? `${defaultLineHeight}px`,
                overflowWrap: "anywhere",
                wordBreak: "normal",
              }}
            >
              {line || "\u200b"}
            </div>
          ))}
        </div>
      </div>
    </>
  );
}
